ValidationRule.errorConditionFormula:
NOT(ISNEW()) &&
ISCHANGED(StageName) &&
(
     (ISPICKVAL(PRIORVALUE(StageName), "Discovery") &&
        ( NOT(ISPICKVAL(StageName, "Solicitation")) && NOT(ISPICKVAL(StageName, "Commited"))
         && NOT(ISPICKVAL(StageName, "Cancelled"))
        ) 
     )||
    (ISPICKVAL(PRIORVALUE(StageName), "Solicitation") &&
       ( NOT(ISPICKVAL(StageName, "Discovery")) && NOT(ISPICKVAL(StageName, "Commited"))
          && NOT(ISPICKVAL(StageName, "Cancelled"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(StageName), "Commited") &&
       (NOT(ISPICKVAL(StageName, "Closed"))
          && NOT(ISPICKVAL(StageName, "Cancelled"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(StageName), "Closed") &&
       ( NOT(ISPICKVAL(StageName, "Cancelled"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(StageName), "Cancelled") &&
       ( NOT(ISPICKVAL(StageName, "Cancelled"))
       ) 
     )

)
&&
$Profile.Name <> 'System Administrator' &&
$Profile.Name <> 'Global Admin'
